<script setup>
import {computed,ref,watch} from 'vue'
import {useArcade} from '../stores/arcade'
import {useRoom} from '../stores/room'
import {roomItems} from '../data/roomItems'
import DressedPartner from './DressedPartner.vue'
const props=defineProps({items:{type:Array,required:true}}),s=useArcade(),room=useRoom(),category=ref('wear'),view=ref('owned'),selectedId=ref(''),page=ref(0),quantity=ref(1),busy=ref(false),notice=ref(''),error=ref('')
const pet=computed(()=>s.data.pet),catalog=computed(()=>category.value==='wear'?(view.value==='shop'?props.items:props.items.filter(i=>pet.value.owned.includes(i.id))):(view.value==='shop'?roomItems:roomItems.filter(i=>room.inventory.some(c=>c.item_id===i.id)))),selected=computed(()=>catalog.value.find(i=>i.id===selectedId.value)),owned=computed(()=>category.value==='wear'?pet.value.owned.includes(selectedId.value):room.inventory.some(i=>i.item_id===selectedId.value)),equipped=computed(()=>category.value==='wear'&&pet.value.wear===selectedId.value),pageCount=computed(()=>Math.max(1,Math.ceil(catalog.value.length/9))),slots=computed(()=>Array.from({length:9},(_,i)=>catalog.value[page.value*9+i]??null)),working=computed(()=>busy.value||room.busy)
watch([category,view],()=>{page.value=0;selectedId.value=catalog.value[0]?.id??'';notice.value='';error.value=''})
watch(catalog,()=>{page.value=Math.min(page.value,pageCount.value-1);if(!catalog.value.some(i=>i.id===selectedId.value))selectedId.value=catalog.value[page.value*9]?.id??''},{immediate:true})
function count(id){return room.inventory.filter(i=>i.item_id===id).length}
function placed(id){return room.design.placements.filter(p=>room.inventory.some(i=>i.id===p.copyId&&i.item_id===id)).length}
function select(item){if(!working.value){selectedId.value=item.id;notice.value='';error.value=''}}
function changePage(n){page.value=Math.max(0,Math.min(pageCount.value-1,page.value+n));selectedId.value=catalog.value[page.value*9]?.id??''}
async function act(){if(!selected.value||working.value)return;const item=selected.value;if(category.value==='room'){if(view.value==='shop'){const before=count(item.id);await room.buy(item.id,Number(quantity.value));if(count(item.id)>before){view.value='owned';selectedId.value=item.id}}else room.choose(item.id);return}if(equipped.value)return;busy.value=true;error.value='';try{const buying=!owned.value;await s.petAction('wear',item.id);notice.value=buying?item.name+' 구매·착용 완료! 내 아이템에 보관됩니다.':item.name+'을 착용했어요!';if(buying)view.value='owned';selectedId.value=item.id}catch(e){error.value=e.message}finally{busy.value=false}}
async function remove(){if(working.value||!pet.value.wear)return;busy.value=true;error.value='';try{await s.petAction('remove');notice.value='벗긴 아이템은 내 아이템에 보관됩니다.'}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><aside class="item-device" aria-label="포켓몬 아이템 슬롯"><div class="device-top"><div class="device-lens" aria-hidden="true"></div><span class="device-indicators" aria-hidden="true"><i></i><i></i><i></i></span><span class="device-brand">SPOKEMON / ITEM CASE</span></div><div class="device-book"><section class="device-left"><div class="device-screen-frame"><div class="screen-dots" aria-hidden="true">● ●</div><div class="device-partner-screen"><DressedPartner size="device"/></div><div class="device-screen-foot" aria-hidden="true"><i></i><span>≡</span></div></div><div class="device-identity"><span>MY PARTNER</span><h3>{{s.petName}}</h3><small v-if="pet.nickname">{{s.partner.name}}</small><b>Lv.{{s.level}}</b></div><div class="device-bottom-controls" aria-hidden="true"><div class="device-green-key"></div><div class="device-dpad"><span>✚</span></div></div><p class="device-lock-note">{{s.data.partnerLocked?'CHANGE · 5,000 P':'CHOOSE YOUR PARTNER'}}</p></section><div class="device-hinge" aria-hidden="true"><i></i><i></i></div><section class="device-right"><div class="device-tabs" aria-label="아이템 종류"><button :class="{active:category==='wear'}" :aria-pressed="category==='wear'" :disabled="working" @click="category='wear'">포켓몬 착용용</button><button :class="{active:category==='room'}" :aria-pressed="category==='room'" :disabled="working" @click="category='room'">방꾸미기</button></div><div class="device-tabs" aria-label="내 아이템과 상점"><button :class="{active:view==='owned'}" :aria-pressed="view==='owned'" :disabled="working" @click="view='owned'">내 아이템</button><button :class="{active:view==='shop'}" :aria-pressed="view==='shop'" :disabled="working" @click="view='shop'">아이템 상점</button></div><div class="device-lcd"><p>{{category==='wear'?'포켓몬 착용용':'방꾸미기'}} · {{view==='owned'?'내 아이템':'상점'}}</p><span v-if="category==='wear'">보유 {{pet.owned.length}}종 / 착용 {{pet.wear?'1':'0'}}개</span><span v-else>보유 {{room.inventory.length}}개 / 배치 {{room.design.placements.length}}개</span><b>🪙 {{s.data.coins.toLocaleString()}}</b></div><p v-if="!catalog.length" class="device-empty-note">아직 구매한 아이템이 없어요. ‘아이템 상점’에서 구경하세요!</p><div class="device-slot-grid" aria-label="아이템 보관함"><button v-for="(item,index) in slots" :key="index" type="button" :class="['device-slot',{selected:item?.id===selectedId,owned:item&&(category==='wear'?pet.owned.includes(item.id):count(item.id)>0),equipped:category==='wear'&&item&&pet.wear===item.id,empty:!item}]" :disabled="!item||working" :aria-label="item?item.name+' 슬롯':'빈 아이템 슬롯 '+(index+1)" :aria-pressed="!!item&&item.id===selectedId" @click="select(item)"><template v-if="item"><span class="device-item-icon">{{category==='wear'?item.id:item.emoji}}</span><small v-if="view==='shop'">{{item.price}} P {{category==='wear'&&pet.owned.includes(item.id)?'· 보유':''}}</small><small v-else-if="category==='room'">{{count(item.id)}}개 · 배치 {{placed(item.id)}}</small><small v-else>{{pet.wear===item.id?'✓ 착용 중':'✓ 보유'}}</small></template><span v-else class="device-slot-empty" aria-hidden="true">＋</span></button></div><div class="device-item-pages"><button :disabled="page===0||working" aria-label="이전 아이템 페이지" @click="changePage(-1)">◀</button><span>{{page+1}} / {{pageCount}}</span><button :disabled="page===pageCount-1||working" aria-label="다음 아이템 페이지" @click="changePage(1)">▶</button></div><div v-if="selected" class="device-item-detail"><h3>{{selected.name}}</h3><p v-if="category==='room'">보유 {{count(selected.id)}}개 · 배치 {{placed(selected.id)}}개 · 보관 중 {{count(selected.id)-placed(selected.id)}}개</p><p v-else>{{equipped?'현재 착용 중':owned?'내 아이템 · 다시 착용은 무료':selected.price+' P · 구매하면 내 아이템에 보관됩니다.'}}</p><label v-if="category==='room'&&view==='shop'" class="device-quantity">구매 수량<input v-model.number="quantity" type="number" min="1" max="99" :disabled="working"/></label><button class="device-action" :disabled="working||(category==='wear'&&(equipped||(view==='shop'&&owned)))||(view==='shop'&&s.data.coins<selected.price*(category==='room'?quantity:1))||(category==='room'&&view==='shop'&&(!Number.isInteger(quantity)||quantity<1||quantity>99))" @click="act">{{working?'처리 중…':category==='room'?(view==='shop'?'구매 · '+selected.price*quantity+' P':'방에 배치 · 위치 편집'):equipped?'✓ 착용 중':view==='shop'?(owned?'✓ 보유 중':'구매·착용 · '+selected.price+' P'):'착용하기'}}</button><p v-if="category==='room'&&view==='owned'">선택 후 왼쪽 방의 원하는 곳을 클릭하세요. 같은 장식도 여러 개 구매해 배치할 수 있어요.</p></div><button v-if="category==='wear'" class="device-remove" :disabled="!pet.wear||working" @click="remove">꾸미기 벗기기</button></section></div><div class="device-footer"><span>{{view==='owned'?'MY ITEMS · 내가 산 아이템':'ITEM SHOP · 새 아이템 구매'}}</span><i aria-hidden="true"></i></div><p v-if="notice" class="device-feedback" role="status">{{notice}}</p><p v-if="error" class="device-feedback device-error" role="alert">{{error}}</p><p v-if="category==='room'&&room.notice" class="device-feedback" role="status">{{room.notice}}</p><p v-if="category==='room'&&room.error" class="device-feedback device-error" role="alert">{{room.error}}</p></aside></template>
<style scoped>
.device-tabs{display:flex;gap:5px;margin:0 0 8px;flex-wrap:wrap}.device-tabs button{flex:1;min-width:75px;padding:8px 4px;font-size:10px;margin:0}.device-tabs button.active{background:var(--rpg-soft)!important;color:var(--rpg-ink)!important;outline:2px solid var(--rpg-edge)}.device-empty-note{background:#fff;color:var(--rpg-ink);padding:10px;font-size:11px;line-height:1.8}.device-quantity{font-size:11px;display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px}.device-quantity input{width:65px;min-width:0;padding:6px}.device-slot small{font-size:8px;white-space:normal}.device-item-detail p{line-height:1.7}
</style>
